import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const u=JSON.parse('{"title":"Policy rules","description":"","frontmatter":{},"headers":[],"relativePath":"admin/policy-rules.md","filePath":"admin/policy-rules.md"}'),s={name:"admin/policy-rules.md"};function d(n,e,c,i,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="policy-rules" tabindex="-1">Policy rules <a class="header-anchor" href="#policy-rules" aria-label="Permalink to &quot;Policy rules&quot;">​</a></h1><p>Every policy has exactly one rule. This page describes each rule, its settings, and how DepGate decides whether a version matches.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Actions</th><th>Recommended start</th></tr></thead><tbody><tr><td><a href="#packages">Packages</a></td><td>Block or Allow</td><td>Enforce</td></tr><tr><td><a href="#release-type">Release type</a></td><td>Block</td><td>Monitor</td></tr><tr><td><a href="#release-age">Release age</a></td><td>Block</td><td>Monitor</td></tr><tr><td><a href="#vulnerability">Vulnerability</a></td><td>Block</td><td>Monitor (Enforce for Critical only)</td></tr><tr><td><a href="#license">License</a></td><td>Block</td><td>Monitor</td></tr><tr><td><a href="#namespace-protection">Namespace protection</a></td><td>Block</td><td>Monitor</td></tr><tr><td><a href="#project-health">Project health</a></td><td>Block</td><td>Monitor</td></tr></tbody></table><p>Allow is offered only for the Packages rule. The other rules cover every package in an ecosystem, and an Allow there would skip every lower-priority policy for all of them.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>Matches named packages, optionally only some of their versions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Package names</strong></td><td>One or more names or patterns, such as <code>event-stream</code> or <code>*-malware</code>.</td></tr><tr><td><strong>Versions</strong> (optional)</td><td>Single versions (<strong>+ Version</strong>) and inclusive ranges (<strong>+ Version range</strong>), such as <code>1.0.0 – 2.0.0</code>. Leave empty to match every version.</td></tr></tbody></table><p>Versions are compared with each ecosystem&#39;s own rules (SemVer, PEP 440, Maven, NuGet, RubyGems, Composer), so names such as <code>2.0.0rc1</code>, <code>1.0-SNAPSHOT</code> or <code>31.1-jre</code> work as expected.</p><p>Use <strong>Block</strong> to stop a known-bad package or version. Use <strong>Allow</strong> with a low priority number to let trusted packages, such as your own, skip the rest of the policies.</p><h2 id="release-type" tabindex="-1">Release type <a class="header-anchor" href="#release-type" aria-label="Permalink to &quot;Release type&quot;">​</a></h2><p>Blocks versions that are not stable releases. Each version has exactly one type, decided by its ecosystem&#39;s conventions.</p><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th><th>Ecosystems</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Pre-release</strong></td><td>Alpha, beta, milestone, release candidate, preview</td><td>All</td><td><code>1.2.3-rc.1</code>, <code>2.0.0rc1</code>, <code>2.0.0-RC1</code>, <code>7.1.0.beta1</code></td></tr><tr><td><strong>Dev release</strong></td><td>Development builds and branch heads</td><td>PyPI, Composer</td><td><code>1.0.dev1</code>, <code>dev-main</code>, <code>1.0.x-dev</code></td></tr><tr><td><strong>Snapshot</strong></td><td>Builds that can change under the same version</td><td>Maven</td><td><code>1.0-SNAPSHOT</code></td></tr><tr><td><strong>Pseudo-version</strong></td><td>Go versions for an untagged commit</td><td>Go</td><td><code>v0.0.0-20240101120000-abcdef123456</code></td></tr></tbody></table><p>The form shows, for each type, which ecosystems it applies to and example versions for the chosen ecosystem. The block reason names the convention that matched, for example <em>Version 2.0.0rc1 is a pre-release (PEP 440 &quot;rc&quot;)</em>.</p><h2 id="release-age" tabindex="-1">Release age <a class="header-anchor" href="#release-age" aria-label="Permalink to &quot;Release age&quot;">​</a></h2><p>Blocks versions by when they were published. Fill in one setting or both.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Matches</th></tr></thead><tbody><tr><td><strong>Published less than</strong> N hours ago</td><td>Versions that are too new. A cool-down gives the community time to discover a compromised or broken release before it reaches you. The version is allowed automatically once it is old enough.</td></tr><tr><td><strong>No release in</strong> N days</td><td>Packages whose latest release is older than N days, a sign the project is no longer maintained.</td></tr></tbody></table><p>Publish dates come from the upstream registry. When a public registry does not provide one, DepGate looks it up on <a href="https://deps.dev" target="_blank" rel="noreferrer">deps.dev</a>. Internal packages are never looked up outside your network.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A 72-hour cool-down blocks the newest release of many popular packages for three days. Developers then get the previous version automatically, which is usually what you want.</p></div><h2 id="vulnerability" tabindex="-1">Vulnerability <a class="header-anchor" href="#vulnerability" aria-label="Permalink to &quot;Vulnerability&quot;">​</a></h2><p>Blocks versions with known vulnerabilities. Vulnerability data comes from <a href="https://osv.dev" target="_blank" rel="noreferrer">OSV</a>, which aggregates GitHub, PyPI, Go, RustSec and other advisory databases.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>CVE IDs</strong></td><td>Block any version affected by these specific vulnerabilities, such as <code>CVE-2021-44228</code>. A listed CVE always matches.</td></tr><tr><td><strong>CVSS score at least</strong></td><td>Block when a vulnerability&#39;s CVSS base score is at least this value (0.1 to 10). Medium starts at 4.0, High at 7.0, Critical at 9.0.</td></tr><tr><td><strong>When a vulnerability has no CVSS score</strong></td><td><strong>Ignore it</strong> (recommended) or <strong>Block the version</strong>. Many Go and some PyPI and Rust advisories are unrated.</td></tr><tr><td><strong>Exploit likelihood (EPSS)</strong></td><td>Optionally, block only vulnerabilities that are likely to be exploited. See below.</td></tr></tbody></table><p>With both CVE IDs and a score filled in, either one is enough to match.</p><p><strong>How the score is chosen.</strong> DepGate computes the base score from the advisory&#39;s CVSS vector, preferring CVSS 4.0, then 3.1, then 3.0. When an advisory has only a severity label, the label counts as the lowest score of its rating (High counts as 7.0).</p><h3 id="exploit-likelihood-epss" tabindex="-1">Exploit likelihood (EPSS) <a class="header-anchor" href="#exploit-likelihood-epss" aria-label="Permalink to &quot;Exploit likelihood (EPSS)&quot;">​</a></h3><p><a href="https://www.first.org/epss/" target="_blank" rel="noreferrer">EPSS</a> estimates, every day, the probability that a CVE will be exploited in the next 30 days. Most vulnerabilities are never exploited; EPSS lets you focus on the ones that are.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>EPSS score at least</strong> N %</td><td>Block when the probability is at least N %.</td></tr><tr><td><strong>EPSS percentile at least</strong></td><td>Alternatively, block the top of the distribution, such as the 95th percentile.</td></tr><tr><td><strong>When a vulnerability has no EPSS score</strong></td><td><strong>Block the version</strong> (default) or <strong>Ignore it</strong>. New CVEs receive a score within a day or so.</td></tr></tbody></table><p><strong>CVSS and EPSS apply to the same vulnerability.</strong> &quot;CVSS at least 7.0 and EPSS at least 10 %&quot; matches a version with a CVSS 7.5 vulnerability at 42 %, but not a version with one CVSS 9.8 vulnerability at 0.1 % and a different CVSS 3.1 vulnerability at 90 %.</p><p>DepGate downloads the full EPSS data set once a day and evaluates policies against that local copy, so EPSS never slows downloads. Because scores change daily, a version may be allowed one day and blocked the next. The data status is under <a href="./jobs">Settings → Jobs</a>.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Blocks versions by their declared license. Choose one of two modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Block every license except the approved ones</strong></td><td>The usual company setup: an approved list, with everything else blocked. Packages with no license information are blocked too, unless you select <strong>Allow packages with no license info</strong>.</td></tr><tr><td><strong>Block only the listed licenses</strong></td><td>A list of banned licenses, such as <code>AGPL-3.0</code>, <code>SSPL-1.0</code> or <code>BUSL-1.1</code>. Every other license passes.</td></tr></tbody></table><p>You can run both: put the banned list at a higher priority so banned licenses name that policy, and the approved list below it.</p><p><strong>How licenses are read</strong></p><ul><li><strong>OR</strong> means the user may choose: <code>MIT OR GPL-3.0</code> passes a policy that approves MIT, and is not blocked by a GPL-3.0 ban.</li><li><strong>AND</strong> means every license applies: <code>MIT AND GPL-3.0</code> needs both approved, and is blocked by a GPL-3.0 ban.</li><li>Entries are SPDX IDs, or patterns such as <code>BSD-*</code>. <code>GPL-3.0</code> also covers <code>GPL-3.0-only</code>, <code>GPL-3.0-or-later</code> and <code>GPL-3.0+</code>. Common names such as <code>Apache License 2.0</code> are mapped to their SPDX ID.</li><li>A license counts as <strong>unknown</strong> when it is missing, <code>UNKNOWN</code>, <code>NOASSERTION</code>, <code>SEE LICENSE IN …</code>, or full license text instead of a name.</li><li>When a public registry does not declare a license, DepGate looks it up on deps.dev.</li></ul><h2 id="namespace-protection" tabindex="-1">Namespace protection <a class="header-anchor" href="#namespace-protection" aria-label="Permalink to &quot;Namespace protection&quot;">​</a></h2><p>Protects your internal package names against <strong>dependency confusion</strong>: an attacker publishing a public package with the same name as one of yours. A Namespace protection policy lists your names for one ecosystem, and DepGate then serves those names only from the remotes you trust (your internal registries by default).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Your package names</strong></td><td>Scopes, prefixes or exact names, such as <code>@acme</code> and <code>acme-*</code> for npm, <code>com.acme</code> for Maven, or <code>github.com/acme</code> for Go.</td></tr><tr><td><strong>Serve only from</strong></td><td>The remotes allowed to serve these names. All internal registries are selected by default.</td></tr><tr><td><strong>Exceptions: allow from any remote</strong></td><td>Names inside your namespaces that you publish publicly on purpose, such as <code>@acme/eslint-config</code>.</td></tr></tbody></table><p>This rule is described in full in <a href="./namespace-protection">Namespace protection</a>.</p><h2 id="project-health" tabindex="-1">Project health <a class="header-anchor" href="#project-health" aria-label="Permalink to &quot;Project health&quot;">​</a></h2><p>Blocks packages whose source repository scores low on the <a href="https://scorecard.dev" target="_blank" rel="noreferrer">OpenSSF Scorecard</a>, which rates projects from 0 to 10 on practices such as maintenance, code review, dangerous CI workflows and pinned dependencies. It measures project hygiene, not malware.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Overall score at least</strong></td><td>The main condition.</td></tr><tr><td><strong>Individual checks</strong> (advanced)</td><td>A minimum for chosen checks, such as <code>Dangerous-Workflow</code> at least 10. Any failing check is enough to match.</td></tr><tr><td><strong>When a package has no Scorecard result</strong></td><td>Allow (default) or block. Happens when the package declares no repository, the repository is not on GitHub or GitLab, or Scorecard has not scanned it.</td></tr><tr><td><strong>When Scorecard can&#39;t be reached</strong></td><td>Allow (default) or block. Blocking means an outage of the Scorecard service blocks every package the policy covers.</td></tr></tbody></table><p>The repository is the one the package declares, which DepGate reads from the registry metadata (with deps.dev as a fallback). Only repositories whose remotes are all public are checked: DepGate never sends internal package names to Scorecard.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Many popular, safe packages score between 3 and 5. Start in monitor mode and pick a threshold from the results.</p></div><h2 id="api-field-names" tabindex="-1">API field names <a class="header-anchor" href="#api-field-names" aria-label="Permalink to &quot;API field names&quot;">​</a></h2><p>When you create policies through the <a href="/depgate/reference/api">REST API</a>, the rule settings go in <code>conditions</code>:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Fields</th></tr></thead><tbody><tr><td>Packages</td><td><code>packageBlockList</code>, <code>versionRange</code></td></tr><tr><td>Release type</td><td><code>releaseTypes</code>: <code>prerelease</code>, <code>dev</code>, <code>snapshot</code>, <code>pseudo</code></td></tr><tr><td>Release age</td><td><code>releaseAgeMaxHours</code>, <code>releaseAgeMinDays</code></td></tr><tr><td>Vulnerability</td><td><code>cveBlockList</code>, <code>cvssMin</code>, <code>cvssUnknown</code>, <code>epssMin</code> or <code>epssPercentileMin</code>, <code>epssUnknown</code></td></tr><tr><td>License</td><td><code>licenseAllowList</code> and <code>allowUnknownLicense</code>, or <code>licenseDenyList</code></td></tr><tr><td>Namespace protection</td><td><code>reservedNamespaces</code>, <code>allowedRemotes</code>, <code>publicPackages</code></td></tr><tr><td>Project health</td><td><code>scorecardMinScore</code>, <code>scorecardChecks</code>, <code>scorecardUnknown</code>, <code>scorecardUnavailable</code></td></tr></tbody></table><p>Every rule also accepts <code>ecosystem</code> (a list; empty means all).</p>',47)])])}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
